@my_opt
def first(name, x):
    click.echo(f"first {name} {x}")

@click.command()
@my_arg
@my_opt
def second(name, x):
    click.echo(f"second {name} {x}")

for cmd in (first, second):
    print(cmd.name, [(type(p).__name__, p.name, p.help, p.default) for p in cmd.params])

assert type(first.params[0]) is MyArgument and type(second.params[0]) is MyArgument
assert type(first.params[1]) is MyOption and type(second.params[1]) is MyOption
assert first.params[0] is not second.params[0]
assert first.params[1] is not second.params[1]

